chrome.runtime.onInstalled.addListener(()=>{console.log("Web to Kindle EPUB extension installed.")});chrome.runtime.onMessage.addListener((e,n,r)=>{if(e.type==="FETCH_IMAGE")return l(e.url).then(r).catch(t=>r({success:!1,error:t.message})),!0;if(e.type==="DOWNLOAD_FILE")return u(e.url,e.filename).then(t=>r({success:!0,downloadId:t})).catch(t=>r({success:!1,error:t.message})),!0});async function l(e){const n=await fetch(e,{headers:{Accept:"image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8"}});if(!n.ok)throw new Error(`Failed to fetch image: ${n.status}`);const r=n.headers.get("content-type")||"image/jpeg",t=await n.arrayBuffer();let a="";const c=new Uint8Array(t),s=c.byteLength;for(let o=0;o<s;o++)a+=String.fromCharCode(c[o]);const i=btoa(a);return{success:!0,contentType:r,base64:i}}async function u(e,n){return new Promise((r,t)=>{chrome.downloads.download({url:e,filename:n,saveAs:!1},a=>{chrome.runtime.lastError?t(chrome.runtime.lastError):r(a)})})}
